import csv, io

def accuracy_by_expected(csv_text):
    counts = {}
    for row in csv.DictReader(io.StringIO(csv_text)):
        right, total = counts.get(row["expected"], (0, 0))
        counts[row["expected"]] = (right + (row["action"] == row["expected"]), total + 1)
    return counts
